// @ts-strict-ignore
import { Meta, StoryObj } from "@storybook/react";
import DialogModal from "./dialog-modal";
import { ContentContainer } from "@/core/components/primitives/content-container/content-container";
import { action } from "storybook/actions";
import { useState } from "react";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { desktopOnlyMode } from "../../../../.storybook/preview";

const meta = {
  title: "Primitives/Dialog Modal",
  component: DialogModal,
  render: function StoryComponent({ ...args }) {
    const [isOpen, setIsOpen] = useState(false);
    const [primaryClickCounter, setPrimaryClickCounter] = useState(0);
    const [secondaryClickCounter, setSecondaryClickCounter] = useState(0);

    return (
      <ContentContainer>
        <div>
          <PrimaryButton label="Öppna modalen" onClick={() => setIsOpen(true)} />
          <p className="story-theme-name" style={{ paddingTop: "1rem" }}>
            Primary klick: {primaryClickCounter}
          </p>
          <p className="story-theme-name">Secondary klick: {secondaryClickCounter}</p>
          {isOpen && (
            <DialogModal
              {...args}
              onCloseFunction={() => setIsOpen(false)}
              primaryButtonAction={() => {
                setPrimaryClickCounter(primaryClickCounter + 1);
                setIsOpen(false);
              }}
              secondaryButtonAction={() => {
                setSecondaryClickCounter(secondaryClickCounter + 1);
                setIsOpen(false);
              }}
            />
          )}
        </div>
      </ContentContainer>
    );
  },
  parameters: {
    chromatic: desktopOnlyMode,
  },
} satisfies Meta<typeof DialogModal>;

export default meta;

export const Primary = {
  args: {
    headingText: "Test Title",
    bodyText: "Testing body text",
    primaryButtonText: "Primary button",
    secondaryButtonText: "Secondary button",
    primaryButtonAction: action("Primary button clicked"),
    secondaryButtonAction: action("Second button clicked"),
    onCloseFunction: action("Close function triggered"),
  },
} satisfies StoryObj<typeof meta>;
